def main():
    assert json.loads((HERE/'numerical_audit.json').read_text())['status']=='PASS'
    (READER/'sources').mkdir(parents=True,exist_ok=True);changes=[];reports={}
    for stem,name,replacements,inserts in [('main','nature_communications_article.md',MAIN,INSERT_MAIN),('supplement','supplementary_information.md',SI,INSERT_SI)]:
        old=json.loads((HERE/'before'/f'{stem}_aligned_blocks.json').read_text());assert old['source_sha256']==h.sha(HERE/'before'/name)
        rows=[]
        for r0 in old['blocks']:
            r=dict(r0)
            if stem=='main' and r['id'] in REMOVE:
                changes.append(dict(id=r['id'],action='removed_from_main; scientific provenance retained in SI/archive',before=r));continue
            if r['id'] in replacements:r['en'],r['zh']=replacements[r['id']]
            for lang in ['en','zh']:r[lang]=r[lang].replace('docs/figures/repeat_mechanism_v1/artwork/','docs/figures/operating_tradeoffs_v1/artwork/')
            if r['id']=='M099':
                r['en']=r['en'].replace('release.<sup>20</sup>','release,<sup>20</sup> with the 2020 GPU trace supplying the separate chronological submission test.<sup>32</sup>')
                r['en']+=' Submission counts, processed submission-time records, frozen scenarios and all 22,400 new replays accompany the structural Source Data.'
                r['zh']+=' 新增独立时序检验采用 Alibaba 2020 GPU 轨迹的提交记录；其计数、处理后时间记录、冻结场景与全部 22,400 次新增重放均随源数据保存。<sup>32</sup>'
            if r['id']=='M027':
                r['en']=r['en'].replace('at most 1% missed work','at most 1% missed eligible work')
                r['zh']=r['zh'].replace('最多 1% 的工作期限违约','最多 1% 的可参与工作期限违约')
            if r['id']=='M076':
                r['en']=r['en'].replace('a deadline-miss fraction no greater','a deadline-miss fraction of eligible work no greater')
                r['zh']+=' 期限违约率的分母为到达的可参与工作 GPU 小时量。'
            if r['id']=='S20_036':
                r['en']=r['en'].replace('expired GPU-hour work divided by offered work','expired eligible GPU-hour work divided by total arriving eligible work').replace('divided by total arrivals','divided by total eligible arrivals')
                r['zh']+='\n\n期限违约与期末积压比例的分母均为全部到达的可参与工作 GPU 小时量。'
            if r['id']=='S20_006':
                r['en']=r['en'].replace('Supplementary Fig. 3; Table 5','Supplementary Fig. 3; Tables 5, 10–11, 13–16').replace('Tables 7, 9','Tables 7, 9, 12, 17')
                r['zh']=r['zh'].replace('补充图 3；表 5','补充图 3；表 5、10–11、13–16').replace('表 7、9','表 7、9、12、17')
            if r['id']=='S20_094':
                r['en']=r['en'].replace('10,000; 25,000; 50,000','0; 1,000; 2,500; 5,000; 10,000; 25,000; 50,000')
                r['zh']=r['zh'].replace('10,000；25,000；50,000','0；1,000；2,500；5,000；10,000；25,000；50,000').replace('10,000; 25,000; 50,000','0; 1,000; 2,500; 5,000; 10,000; 25,000; 50,000')
            if r!=r0:changes.append(dict(id=r['id'],action='replace',before=r0,after=r))
            rows.append(r)
            for new in inserts.get(r['id'],[]):rows.append(dict(new));changes.append(dict(id=new['id'],action='add',after=new))
        if stem=='supplement':
            rows.extend(tables())
            mapping=json.loads((HERE/'reference_number_map.json').read_text())
            for row in rows:
                if row['id']=='S023_temporal_methods':
                    for lang in ['en','zh']:row[lang]=row[lang].replace('<sup>32</sup>',f'<sup>{mapping["32"]}</sup>')
        else:rows=h.renumber_references(rows)
        header=f'<!--\nWorking {"manuscript" if stem=="main" else "Supplementary Information"}, version 0.23, 2026-09-10.\nAudited structural service tests, independent timing transfer and separated operating/access costs.\nAuthor metadata remain pending.\n-->\n\n'
        document=header+'\n\n'.join(r['en'] for r in rows)+'\n';path=ROOT/'manuscript'/name;path.write_text(document);(READER/'sources'/f'{stem}_original.md').write_text(document)
        note='本稿逐段对应正文与补充材料 v0.23（2026-09-10）。新增零违约与结构检验、八周生产提交时序对照、费用分解和时长产品选择；保留原有证据的适用范围。\n\n'
        cn=[];both=[]
        for r in rows:
            en,zh=h.reader_format(r['en']),h.reader_format(r['zh']);cn.append(zh);both.extend([zh] if en.startswith(('![','$$')) else [f'<!-- {r["id"]} -->\n{en}',zh])
        (READER/f'{stem}_zh.md').write_text(note+'\n\n'.join(cn)+'\n');(READER/f'{stem}_bilingual.md').write_text(note+'\n\n'.join(both)+'\n')
        (READER/f'{stem}_aligned_blocks.json').write_text(json.dumps(dict(source_sha256=h.sha(path),blocks=rows),ensure_ascii=False,indent=2)+'\n')
        def wc(t):return len(re.findall(r"\b[\w]+(?:[-’'][\w]+)*\b",t))
        reports[stem]=dict(status='PASS',blocks=len(rows),source_sha256=h.sha(path),old_words=wc((HERE/'before'/name).read_text()),new_words=wc(document))
        if stem=='main':
            reports[stem]['abstract_words']=wc(next(r['en'] for r in rows if r['id']=='M006'))
            reports[stem]['results_words']=wc(document.split('## Results\n')[1].split('## Discussion\n')[0])
    (HERE/'text_changes.json').write_text(json.dumps(changes,ensure_ascii=False,indent=2)+'\n');(HERE/'revision_validation.json').write_text(json.dumps(reports,indent=2)+'\n')
    (READER/'README.md').write_text('# 中文阅读稿 v17\n\n对应正文与补充材料 v0.23，包含新的结构与零期限违约检验、八周生产时序对照和费用拆分。\n\n- [正文中文全文](main_zh.md)\n- [补充材料中文全文](supplement_zh.md)\n- [正文中英对照](main_bilingual.md)\n- [补充材料中英对照](supplement_bilingual.md)\n')
    print(json.dumps(reports,indent=2))

if __name__=='__main__':main()
